import {detectiveArt} from '../reading/ui.js';
import {THEMES,PROFILES} from './model.js';
import {esc} from './parent.js';
const hex=n=>'#'+n.toString(16).padStart(6,'0');
function explorer(x,y,scale=1){return `<g transform="translate(${x} ${y}) scale(${scale})"><ellipse cy="8" rx="24" ry="7" fill="#0d193b44"/><path d="M-15-43h30v32H-15z" fill="#f5bf6a"/><path d="M-14-9l-5 17h11l8-18M4-10L9 8h12l-6-19" fill="#405378"/><path d="M-20-39l-8 22m48-22 8 22" stroke="#ffd7b3" stroke-width="9" stroke-linecap="round"/><circle cy="-64" r="20" fill="#ffdbba"/><path d="M-24-67q24-41 48 0z" fill="#ffe095"/><rect x="-26" y="-68" width="52" height="7" rx="3" fill="#ffdf91"/><circle cx="7" cy="-61" r="2.5" fill="#273b59"/><path d="M1-51q7 5 11-1" stroke="#ac735e" fill="none" stroke-width="2"/></g>`;}
export function modeArt(theme,kind,profile){const t=THEMES[theme],space=theme==='cosmic'||theme==='underwater',a=hex(t.edge),b=hex(t.crystal);return `<svg viewBox="0 0 700 260" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><linearGradient id="${kind}-sky" x2="0" y2="1"><stop stop-color="${hex(t.sky)}"/><stop offset="1" stop-color="${hex(t.fog)}"/></linearGradient><linearGradient id="${kind}-path" x2="0" y2="1"><stop stop-color="${hex(t.road)}"/><stop offset="1" stop-color="#b2948b"/></linearGradient></defs><path fill="url(#${kind}-sky)" d="M0 0h700v260H0z"/>${Array.from({length:12},(_,i)=>`<circle cx="${(i*137+35)%700}" cy="${12+i%4*29}" r="${i%3+1}" fill="#fff1cd" opacity=".6"/>`).join('')}${space?`<circle cx="570" cy="60" r="55" fill="${b}" opacity=".7"/><ellipse cx="570" cy="60" rx="82" ry="20" stroke="${a}" fill="none" stroke-width="7" transform="rotate(-20 570 60)"/>`:`<path d="M-60 220L130 15 290 220M380 220L555 10 760 220" fill="${a}" opacity=".25"/><path d="M110 39l20-24 23 30-22-10zM535 39l20-29 21 30-21-8z" fill="${b}" opacity=".6"/>`}${kind==='runner'?`<path d="M0 260L315 96h70l315 164" fill="url(#${kind}-path)"/><path d="M0 260L315 96m70 0 315 164" stroke="${a}" stroke-width="6"/><g fill="${hex(t.road)}" stroke="${a}" stroke-width="4"><path d="M135 55h25v135h-25zM525 55h25v135h-25z"/><path d="M120 47h445v20H120z"/></g><g fill="${b}" stroke="#ffffff99">${[0,1,2,3].map(i=>`<path d="M${345+i*7} ${114+i*28}l-8 12 8 12 8-12z"/>`).join('')}</g><path d="M423 147h40v28h-40z" fill="#ec9d79"/>${explorer(300,250,1.3)}<g transform="translate(420 236)"><ellipse rx="22" ry="14" fill="#9acbb9"/><circle cx="-12" cy="-17" r="14" fill="#aee2bd"/><path d="M-23-24l-3-15 15 13m12 14 24-6" stroke="#aee2bd" stroke-width="9" stroke-linecap="round"/></g>`:`<path d="M0 227h190v33H0zM230 195h135v65H230zM411 230h289v30H411z" fill="${hex(t.road)}"/><path d="M0 222h190m40-32h135m46 35h289" stroke="${b}" stroke-width="9" stroke-linecap="round"/>${explorer(297,178,1.05)}<g fill="${b}" stroke="#fff9">${[0,1,2].map(i=>`<path d="M${470+i*55} ${162-i%2*40}l-13 21 13 21 13-21z"/>`).join('')}</g>${profile==='kal'?'<g transform="translate(125 150)"><rect x="-28" y="-28" width="56" height="46" rx="15" fill="#c1f2ec"/><rect x="-19" y="-14" width="38" height="18" rx="6" fill="#34556b"/><path d="M-8-5h3m10 0h3" stroke="#a7ffd3" stroke-width="5"/><path d="M0-29v-15" stroke="#e4c981" stroke-width="5"/><circle cy="-47" r="7" fill="#ffe4a2"/></g>':'<g transform="translate(113 187)"><path d="M-45 0h90v39h-90z" fill="#ac7159"/><path d="M-45 0q0-47 45-47T45 0z" fill="#e5b87b"/><path d="M-45 0h90" stroke="#ffe8a8" stroke-width="7"/><path d="M-8-2h16v22H-8z" fill="#ffe8a8"/></g>'}`}</svg>`;}
export function modeMenu({id,p,pack,resume,rate}){return `<section class="mode-menu ${resume?'with-continue':''}" aria-label="Choose your game"><header class="mode-top"><button id="home" class="menu-back" aria-label="Back to Arcade">‹ <span>Arcade</span></button><div class="mode-location"><span>${id==='ari'?'🌋':'🪐'}</span><div><small>CHOOSE YOUR GAME</small><h2>${PROFILES[id].name}</h2></div></div><div class="menu-balance">◆ ${p.collection.wallet}<small>crystals</small></div><button id="explorer-menu" class="explorer-menu" aria-label="My Explorer">👤</button><button id="menu-settings" class="gear-shortcut" aria-label="Parent Settings">⚙</button></header><div class="selected-study"><span class="test-icon">📖</span><div><small>${rate.past?'PAST TEST':'CURRENT TEST'}</small><strong class="pack-title">${esc(pack.title)}</strong></div><button id="levels" class="tiny-link">Change Test</button>${rate.past?`<span class="reward-label">${Math.round(rate.crystals*100)}% crystals · ${Math.round(rate.xp*100)}% pet XP</span>`:''}</div>${resume?`<button class="continue-adventure" id="continue-adventure"><span>✦</span><div><strong>Continue Adventure</strong><small>${resume.mode==='runner'?'Crystal Quest':PROFILES[id].subtitle} · ${THEMES[resume.world].name} · Stage ${resume.stage+1}</small></div><b>➜</b></button>`:''}<div class="game-modes"><article class="mode-card runner-card"><div class="mode-illustration">${modeArt(p.theme,'runner',id)}<span class="mode-tag">TEMPLE RUN</span></div><div class="mode-card-body"><div><h3>Temple Run</h3><p>Run, dodge & discover!</p></div><button class="mode-play" id="new-run">Play ➜</button></div><div class="mode-card-foot"><span>Seven destinations · three stages each</span></div></article><article class="mode-card original-card"><div class="mode-illustration">${modeArt(id==='kal'?'cosmic':'volcano','original',id)}<span class="mode-tag">ORIGINAL ADVENTURE</span></div><div class="mode-card-body"><div><h3>Original Adventure</h3><p>${PROFILES[id].subtitle} · Jump & explore.</p></div><button class="mode-play" id="original-play">Play ➜</button></div><div class="mode-card-foot"><span>Seven destinations · your current test</span></div></article><article class="mode-card reading-card"><div class="mode-illustration reading-preview">${detectiveArt()}<span class="mode-tag">READING DETECTIVE</span></div><div class="mode-card-body"><div><h3>Reading Detective</h3><p>Find clues. Solve your case.</p></div><button class="mode-play" id="reading-play">Play ➜</button></div><div class="mode-card-foot"><span>Your homework · your discoveries</span></div></article></div><button id="practice" class="practice-strip"><span class="practice-emblem">✦</span><span><strong>Practice for Test</strong><small>Everything, mistakes & flashcards</small></span><span class="practice-arrow">›</span></button><footer class="mode-shortcuts"><div class="collection-links"><button id="store"><span>🛍️</span>Store</button><button id="pets"><span>🐾</span>My Pets</button><button id="rewards"><span>🏆</span>Rewards</button></div><div class="quiet-toggles"><button id="voice">🔊 Voice ${p.narration?'on':'off'}</button><button id="sound">♪ Sound ${p.sound?'on':'off'}</button></div></footer></section>`;}
